3	/**
4	 * Thrown when a create-owner request carries a normalized telephone number that is already used by
5	 * another owner. Handled globally by {@link DuplicateTelephoneExceptionHandler}, which responds 409.
6	 */
7	public class DuplicateTelephoneException extends Exception {
8	
9	    private final String telephone;
10	
11	    public DuplicateTelephoneException(String telephone) {
12	        super("Telephone already in use: " + telephone);
13	        this.telephone = telephone;
14	    }
15	
16	    public String getTelephone() {
17	        return this.telephone;
18	    }
19	}
